    id: 'wstg-conf-04',
    code: 'WSTG-CONF-04',
    reference: 'https://wstg.owasp.org/latest/06-Configuration_and_Deployment_Management/03-Review_Old_Backup_and_Unreferenced_Files_for_Sensitive_Information/',
    area: 'Web',
